            activeWorkOrder: state.activeWorkOrder,
            trackingEnabled: state.trackingEnabled,
            productionStarted: state.productionStarted,
            kpis: state.kpis
        }
    };
    return finalize([null, homeMsg, null, null]);
}

// ========================================================
// MODE: RESTORE QUERY (startup state recovery)
// ========================================================
if (mode === "restore-query") {
    const rows = Array.isArray(msg.payload) ? msg.payload : [];

    if (rows.length > 0) {
        const row = rows[0];
        const restoredOrder = {
            id: row.work_order_id || row.id || "",
            sku: row.sku || "",
            target: Number(row.target_qty || row.target || 0),
            goodParts: Number(row.good_parts || row.goodParts || 0),
            scrapParts: Number(row.scrap_parts || row.scrapParts || 0),
            progressPercent: Number(row.progress_percent || 0),
            cycleTime: Number(row.cycle_time || 0),
            lastUpdateIso: toIsoString(row.updated_at ?? row.last_update),
            cavities: Number(row.cavities_active || 0),
            cavities_total: Number(row.cavities_total || 0)
        };

        attachMold(restoredOrder);

        if (Number(restoredOrder.cavities) > 0) {
            state.lastMoldActive = Number(restoredOrder.cavities);
        }
        if (Number(restoredOrder.cavities_total) > 0) {
            state.lastMoldTotal = Number(restoredOrder.cavities_total);
        }
        if (restoredOrder.id && Number(restoredOrder.cavities) > 0) {
            const map = state.moldByWorkOrder || {};
            map[restoredOrder.id] = {
                total: Number(restoredOrder.cavities_total) > 0 ? Number(restoredOrder.cavities_total) : (state.lastMoldTotal ?? null),
                active: Number(restoredOrder.cavities)
            };
            state.moldByWorkOrder = map;
        }

        const restoredCycleCount = Number(row.cycle_count) || 0;
        const restoredGood = Number(row.good_parts || 0);
        const restoredScrap = Number(row.scrap_parts || 0);
        const hasProgress = restoredCycleCount > 0 || (restoredGood + restoredScrap) > 0;

        // Restore global state
        state.activeWorkOrder = restoredOrder;
        state.cycleCount = restoredCycleCount;
        // Auto-resume tracking for RUNNING work order
        state.trackingEnabled = true;
        state.productionStarted = true;
        state.kpiStartupMode = !hasProgress;

        // Reset tick so KPI integration doesn't jump
        state.kpiLastTick = null;

        let restoreTs = Date.parse(row.updated_at || "");
        if (!isFinite(restoreTs)) {
            restoreTs = Date.now();
        }
        state.lastMachineCycleTime = restoreTs;
        state.lastCycleCompletionTime = restoreTs;

        node.warn('[RESTORE] Restored work order: ' + restoredOrder.id + ' with ' + state.cycleCount + ' cycles');

        const homeMsg = {
            topic: "activeWorkOrder",
            payload: restoredOrder
        };

        const stateMsg = {
            topic: "machineStatus",
            payload: {
                machineOnline: true,
                productionStarted: true,
                trackingEnabled: true
            }
        };

        // Set status back to RUNNING in database (if not already DONE)
        // This prevents user from having to "Load" the work order again
        const dbMsg = {
            topic: "UPDATE work_orders SET status = 'RUNNING', updated_at = NOW() WHERE work_order_id = ? AND status != 'DONE'",
            payload: [restoredOrder.id]
        };


        return finalize([dbMsg, [homeMsg, stateMsg], null, null]);
    } else {
        node.warn('[RESTORE] No running work order found');
    }
    return finalize([null, null, null, null]);
}

