    state.lastMoldActive = moldCache.lastMoldActive;
  }
  if (!Number.isFinite(state.lastMoldTotal) && Number.isFinite(moldCache.lastMoldTotal)) {
    state.lastMoldTotal = moldCache.lastMoldTotal;
  }
  if (!state.moldByWorkOrder && moldCache.moldByWorkOrder && typeof moldCache.moldByWorkOrder === "object") {
    state.moldByWorkOrder = moldCache.moldByWorkOrder;
  }
}

// KPI Buffer for averaging
if (!Array.isArray(state.kpiBuffer)) {
  state.kpiBuffer = [];
  node.warn("[INIT] Set state.kpiBuffer to []");
}

// Last KPI record time - set to 1 min ago for immediate first record
if (typeof state.lastKPIRecordTime !== "number") {
  state.lastKPIRecordTime = Date.now() - 60000;
  node.warn("[INIT] Set state.lastKPIRecordTime");
}

// Last machine cycle time - set to now to prevent immediate 0% availability
if (typeof state.lastMachineCycleTime !== "number") {
  state.lastMachineCycleTime = Date.now();
  node.warn("[INIT] Set state.lastMachineCycleTime to prevent 0% availability on startup");
}

// Last KPI values
if (!state.lastKPIValues || typeof state.lastKPIValues !== "object") {
  state.lastKPIValues = {};
  node.warn("[INIT] Set state.lastKPIValues to {}");
}

// KPI Startup Mode - ensure clean state on deploy
state.kpiStartupMode = false;
node.warn("[INIT] Set state.kpiStartupMode to false");

// Tracking flags - ensure clean state
if (typeof state.trackingEnabled !== "boolean") {
  state.trackingEnabled = false;
}
if (typeof state.productionStarted !== "boolean") {
  state.productionStarted = false;
}

// Settings defaults
if (!Array.isArray(settings.shifts) || settings.shifts.length === 0) {
  settings.shifts = [{ start: "06:00", end: "15:00" }];
  node.warn("[INIT] Set default shift: 06:00-15:00");
}

if (typeof settings.shiftChangeCompensation !== "number") {
  settings.shiftChangeCompensation = 10;
}

if (typeof settings.lunchBreakMinutes !== "number") {
  settings.lunchBreakMinutes = 30;
}

if (typeof settings.thresholdMultiplier !== "number") {
  settings.thresholdMultiplier = 1.5;
}

// State defaults
if (typeof state.operatingTime !== "number") {
  state.operatingTime = 0;
}

if (typeof state.stopTime !== "number") {
  state.stopTime = 0;
}

if (typeof state.plannedProductionTime !== "number") {
  state.plannedProductionTime = 0;
}

if (!Object.prototype.hasOwnProperty.call(state, "lastCycleCompletionTime")) {
  state.lastCycleCompletionTime = null;
}

global.set("settings", settings);
try {
  global.set("settings", settings, "file");
} catch (err) {
  // ignore if file store is not configured
}
global.set("state", state);
const moldCacheOut = {
  lastMoldActive: state.lastMoldActive ?? null,
  lastMoldTotal: state.lastMoldTotal ?? null,
  moldByWorkOrder: state.moldByWorkOrder || {}
};
global.set("moldCache", moldCacheOut);
try {
  global.set("moldCache", moldCacheOut, "file");
} catch (err) {
  // ignore if file store is not configured
}

node.warn("[INIT] Global variable initialization complete");

// Trigger restore-session to check for running work orders
const restoreMsg = { action: "restore-session" };
return [null, restoreMsg];

// Handle DB result from start-work-order progress check
const state = global.get("state") || {};
const persistMoldCache = () => {
    const cache = {
        lastMoldActive: state.lastMoldActive ?? null,
        lastMoldTotal: state.lastMoldTotal ?? null,
        moldByWorkOrder: state.moldByWorkOrder || {}
    };
    global.set("moldCache", cache);
    try {
        global.set("moldCache", cache, "file");
    } catch (err) {
        // ignore if file store is not configured
    }
};

const persistState = () => {
    global.set("state", state);
};

if (msg._mode === "start-check-progress") {
    const order = flow.get("pendingWorkOrder");

    if (!order || !order.id) {
        node.error("No pending work order found", msg);
        return [null, null];
    }

    // Get progress from DB query result
    const dbRow = (Array.isArray(msg.payload) && msg.payload.length > 0) ? msg.payload[0] : null;
    const cycleCount = dbRow ? (Number(dbRow.cycle_count) || 0) : 0;
    const goodParts = dbRow ? (Number(dbRow.good_parts) || 0) : 0;
    const scrapParts = dbRow ? (Number(dbRow.scrap_parts) || 0) : 0;
    const targetQty = dbRow ? (Number(dbRow.target_qty) || 0) : (Number(order.target) || 0);
    const cavitiesTotal = dbRow ? (Number(dbRow.cavities_total) || 0) : 0;
    const cavitiesActive = dbRow ? (Number(dbRow.cavities_active) || 0) : 0;

    const hasProgress = cycleCount > 0 || (goodParts + scrapParts) > 0;
    state.activeOrderHasProgress = hasProgress;
    state.activeOrderId = order.id;


    node.warn(`[PROGRESS-CHECK] WO ${order.id}: cycles=${cycleCount}, good=${goodParts}, target=${targetQty}`);

    // Check if work order has existing progress
    if (hasProgress) {
        // Work order has progress - send prompt to UI
        node.warn(`[PROGRESS-CHECK] Work order has existing progress - sending prompt to UI`);

        if (Number.isFinite(cavitiesActive) && cavitiesActive > 0) {
            order.cavities = cavitiesActive;
        }
        if (Number.isFinite(cavitiesTotal) && cavitiesTotal > 0) {
            order.cavities_total = cavitiesTotal;
        }

        const promptMsg = {
            _mode: "resume-prompt",
            topic: "resumePrompt",
            payload: {
                id: order.id,
                sku: order.sku || "",
                cycleCount: cycleCount,
                goodParts: goodParts,
                targetQty: targetQty,
                progressPercent: targetQty > 0 ? Math.round((goodParts / targetQty) * 100) : 0,
                // Include full order object for resume/restart actions
                order: { ...order, cycleCount: cycleCount, goodParts: goodParts, scrapParts: scrapParts }
            }
        };

        persistState();
        persistMoldCache();
        return [null, promptMsg];
    } else {
        // No existing progress - proceed with normal start
        // But still use DB values (even if 0) to ensure DB is source of truth
        node.warn(`[PROGRESS-CHECK] No existing progress - proceeding with normal start`);

        state.activeOrderHasProgress = false;

        // Update order object with DB values (makes DB the source of truth)
        order.cycleCount = cycleCount;  // Will be 0 from DB
        order.goodParts = goodParts;    // Will be 0 from DB
        order.scrapParts = scrapParts;        // Will be 0 from DB
        order.target = targetQty;        // From DB

        const moldByWorkOrder = state.moldByWorkOrder || {};
        const mapped = moldByWorkOrder[order.id] || {};
        const resolvedCavities = Number(
            order.cavities ?? cavitiesActive ?? mapped.active ?? state.lastMoldActive ?? 0
        );
        const resolvedTotal = Number(
            order.cavities_total ?? cavitiesTotal ?? mapped.total ?? state.lastMoldTotal ?? 0
        );
        if (Number.isFinite(resolvedCavities) && resolvedCavities > 0) {
            order.cavities = resolvedCavities;
            state.lastMoldActive = resolvedCavities;
        }
        if (Number.isFinite(resolvedTotal) && resolvedTotal > 0) {
            order.cavities_total = resolvedTotal;
            state.lastMoldTotal = resolvedTotal;
        }
        if (Number.isFinite(resolvedCavities) && resolvedCavities > 0) {
            moldByWorkOrder[order.id] = {
                total: Number.isFinite(resolvedTotal) && resolvedTotal > 0 ? resolvedTotal : (state.lastMoldTotal ?? null),
                active: resolvedCavities
            };
            state.moldByWorkOrder = moldByWorkOrder;
        }

        const startMsg = {
            _mode: "start",
            startOrder: order,
            topic: "UPDATE work_orders SET status = CASE WHEN work_order_id = ? THEN 'RUNNING' ELSE 'PENDING' END, updated_at = CASE WHEN work_order_id = ? THEN NOW() ELSE updated_at END, cavities_total = COALESCE(NULLIF(?,0), cavities_total), cavities_active = COALESCE(NULLIF(?,0), cavities_active) WHERE status <> 'DONE'",
            payload: [order.id, order.id, Number(order.cavities_total || 0), Number(order.cavities || 0)]
        };

        // Initialize global state with DB values (even if 0)
        state.activeWorkOrder = order;
        persistState();
        state.cycleCount = cycleCount;
        persistState();  // Use DB value instead of hardcoded 0
        flow.set("lastMachineState", 0);
        state.scrapPromptIssuedFor = null;
        persistState();
        persistMoldCache();

        node.warn(`[PROGRESS-CHECK] Initialized from DB: cycles=${cycleCount}, good=${goodParts}, scrap=${scrapParts}`);

        return [startMsg, null];
    }
}

// Pass through all other messages
return [msg, null];

// ============================================================
// DATA MERGER - Combines Cycle + KPI data for Anomaly Detector
// ============================================================

const state = global.get("state") || {};
const settings = global.get("settings") || {};

// Get KPIs from incoming message (from Calculate KPIs node)
const kpis = msg.kpis || msg.payload?.kpis || {};

// Get cycle data from global context
const activeOrder = state.activeWorkOrder || {};
const cycleCount = state.cycleCount || 0;
const moldByWorkOrder = state.moldByWorkOrder || {};
const cavities = Number(
    activeOrder.cavities ??
    moldByWorkOrder[activeOrder.id]?.active ??
    state.lastMoldActive ??
    settings.moldActive ??
    0
);
const lastActualCycleTime = Number(state.lastActualCycleTime || 0);


// Build cycle object with all necessary data
const cycle = {
    id: activeOrder.id,
    sku: activeOrder.sku || "",
    cycles: cycleCount,
    goodParts: Number(activeOrder.goodParts) || 0,
    scrapParts: Number(activeOrder.scrapParts) || 0,
    target: Number(activeOrder.target) || 0,
    cycleTime: Number(activeOrder.cycleTime || activeOrder.theoreticalCycleTime || 0),
    progressPercent: Number(activeOrder.progressPercent) || 0,
    cavities: cavities,
    actualCycleTime: lastActualCycleTime

};

// Merge both into the message
msg.cycle = cycle;
msg.kpis = kpis;

//node.warn(`[DATA MERGER] Merged cycle (count: ${cycleCount}) + KPIs (OEE: ${kpis.oee || 0}%) for anomaly detection`);

return msg;

// ============================================================
// ANOMALY DETECTOR - FIXED VERSION
// Key fixes:
// 1. Removed duplicate suppression that blocks microstop alerts
// 2. Added periodic updates for active macrostops
// 3. Improved logging for debugging
// ============================================================

const state = global.get("state") || {};
const settings = global.get("settings") || {};
const anomaly = global.get("anomaly", "file") || {};

const cycle = msg.cycle || {};
const kpis = msg.kpis || {};
const activeOrder = state.activeWorkOrder || {};
const cycleCountNow = Number(cycle.cycles || 0);


// Must have active work order to detect anomalies
if (!activeOrder.id) {
    return null;
}

const theoreticalCycleTime = Number(activeOrder.cycleTime) || 0;
const now = Date.now();

// Get or initialize anomaly tracking state
let anomalyState = global.get("anomalyState", "file") || {
    lastCycleTime: Number(state.lastMachineCycleTime || now),
    //lastCycleCount: cycleCountNow,
    lastCycleCount: 0,
    activeStoppageEvent: null,
    oeeHistory: [],
    performanceHistory: [],
    qualityHistory: [],
    activeOeeDrop: false,
    oeeLowStreak: 0,
    activeQualitySpike: false,
    qualityHighStreak: 0,
    lastSlowCycleCount: 0,
    lastCycleEventCount: 0,
    lastStoppageUpdateMs: 0
};
// Reset anomaly cycle baseline when work order changes
if (anomalyState.work_order_id && anomalyState.work_order_id !== activeOrder.id) {
    node.warn(`[RESET] Work order changed ${anomalyState.work_order_id} -> ${activeOrder.id}. Resetting anomalyState counters.`);
    anomalyState.lastCycleCount = 0;
    anomalyState.lastCycleEventCount = 0;
    anomalyState.lastSlowCycleCount = 0;
    anomalyState.activeStoppageEvent = null;
    anomalyState.lastStoppageUpdateMs = 0;
}
anomalyState.work_order_id = activeOrder.id;

if (!isFinite(anomalyState.lastCycleTime)) {
    anomalyState.lastCycleTime = Number(state.lastMachineCycleTime || now);
}
if (!isFinite(anomalyState.lastCycleCount)) {
    anomalyState.lastCycleCount = cycleCountNow;
}

const stateLastCycleTime = Number(state.lastMachineCycleTime || 0);
//node.warn(`[TS CHECK] state.lastMachineCycleTime=${stateLastCycleTime} iso=${stateLastCycleTime ? new Date(stateLastCycleTime).toISOString() : 'n/a'}`);
let lastCycleTime = Number(anomalyState.lastCycleTime || 0);
if (stateLastCycleTime > 0 && (lastCycleTime <= 0 || stateLastCycleTime > lastCycleTime)) {
    lastCycleTime = stateLastCycleTime;
}
const prevCount = Number(anomalyState.lastCycleCount || 0);

// If PLC/logic reset the counter (or new batch), re-baseline
if (cycleCountNow > 0 && prevCount > 0 && cycleCountNow < prevCount) {
    node.warn(`[RESET] cycle counter reset detected: ${prevCount} -> ${cycleCountNow}. Re-baselining.`);
    anomalyState.lastCycleCount = cycleCountNow;
    anomalyState.lastCycleTime = stateLastCycleTime > 0 ? stateLastCycleTime : now;
    anomalyState.lastCycleEventCount = cycleCountNow;
    anomalyState.lastSlowCycleCount = cycleCountNow;
    anomalyState.activeStoppageEvent = null;
    anomalyState.lastStoppageUpdateMs = 0;
}
const hasNewCycle = cycleCountNow > Number(anomalyState.lastCycleCount || 0);
//node.warn(`[CYCLE CHECK PRE] cycleCountNow: ${cycleCountNow}, lastCycleCount: ${anomalyState.lastCycleCount}, hasNewCycle: ${cycleCountNow > Number(anomalyState.lastCycleCount || 0)}`);
//node.warn(`[TS CHECK] stateLastCycleTime=${stateLastCycleTime} iso=${stateLastCycleTime ? new Date(stateLastCycleTime).toISOString() : 'n/a'}`);
if (hasNewCycle) {
    anomalyState.lastCycleCount = cycleCountNow;
    anomalyState.lastCycleTime = stateLastCycleTime > 0 ? stateLastCycleTime : now;
    lastCycleTime = anomalyState.lastCycleTime;
}
//node.warn(`[CYCLE CHECK] cycleCountNow: ${cycleCountNow}, lastCycleCount: ${anomalyState.lastCycleCount}, hasNewCycle: ${hasNewCycle}`);
//node.warn(`[CYCLE CHECK] msg.cycle.cycles: ${msg.cycle.cycles}, type: ${typeof msg.cycle.cycles}`);
// Configuration
const OEE_THRESHOLD = settings.oeeAlertThreshold || 90;
const HISTORY_WINDOW = 20;
const QUALITY_SPIKE_THRESHOLD = 5;
const PERFORMANCE_THRESHOLD = settings.performanceThreshold || 85;
const microMultiplier = Number(settings.thresholdMultiplier || 1.5);
const macroMultiplier = Math.max(
    microMultiplier,
    Number(settings.macroStoppageMultiplier || 5)
);

// NEW: Update interval for macrostop notifications (default 10 seconds)
const updateIntervalMs = Number(settings.stoppageUpdateIntervalMs || 10000);

const detectedAnomalies = [];

// ============================================================
// TIER 1: CYCLE CLASSIFICATION + STOPPAGE WATCHDOG
// ============================================================
if (theoreticalCycleTime > 0) {
    const actualCycleTime = Number(cycle.actualCycleTime || 0);
    const currentCycleCount = Number(cycle.cycles || 0);
    const lastCycleEventCount = Number(
        anomalyState.lastCycleEventCount ?? anomalyState.lastSlowCycleCount ?? 0
    );

    const microThresholdSec = theoreticalCycleTime * microMultiplier;
    const macroThresholdSec = theoreticalCycleTime * macroMultiplier;
    const timeSinceLastCycleSec = lastCycleTime > 0 ? (now - lastCycleTime) / 1000 : 0;

    // DEBUG LOGGING
   // node.warn(`[DEBUG] actualCycleTime: ${actualCycleTime}s, theoretical: ${theoreticalCycleTime}s`);
  //  node.warn(`[DEBUG] microThreshold: ${microThresholdSec}s, macroThreshold: ${macroThresholdSec}s`);
 //   node.warn(`[DEBUG] timeSinceLastCycle: ${timeSinceLastCycleSec}s, hasNewCycle: ${hasNewCycle}`);

    let resolvedStoppageThisCycle = false;

    // Resolve any active stoppage when a new cycle arrives
    if (anomalyState.activeStoppageEvent && hasNewCycle) {
        const resolvedDurationSec = actualCycleTime > 0 ? actualCycleTime : timeSinceLastCycleSec;

        detectedAnomalies.push({
            ...anomalyState.activeStoppageEvent,
            status: "resolved",
            resolved_at: now,
            auto_resolved: true,
            data: {
                ...anomalyState.activeStoppageEvent.data,
                stoppage_duration_seconds: Math.round(resolvedDurationSec)
            },
            tsMs: now
        });

        node.warn(`[RESOLVED] Stoppage resolved: ${anomalyState.activeStoppageEvent.anomaly_type}, duration: ${resolvedDurationSec}s`);
        anomalyState.activeStoppageEvent = null;
        anomalyState.lastStoppageUpdateMs = 0;
        resolvedStoppageThisCycle = true;
    }

    if (hasNewCycle) {
        //node.warn(`[CYCLE RESUME] New cycle detected! Count: ${cycleCountNow}, lastCount: ${anomalyState.lastCycleCount}`);
        //node.warn(`[CYCLE RESUME] lastCycleTime updated from ${lastCycleTime} to ${anomalyState.lastCycleTime}`);
        //node.warn(`[CYCLE RESUME] activeStoppageEvent cleared: ${anomalyState.activeStoppageEvent === null}`);
    }

    // Add before the periodic update section (around line ~270)
   // if (anomalyState.activeStoppageEvent) {
      //  node.warn(`[WATCHDOG] Active stoppage exists: ${anomalyState.activeStoppageEvent.anomaly_type}`);
        //node.warn(`[WATCHDOG] timeSinceLastCycle: ${timeSinceLastCycleSec}s, lastCycleTime: ${lastCycleTime}, now: ${now}`);
  //  }

    // Per-cycle classification (uses actualCycleTime)
    if (actualCycleTime > 0 && currentCycleCount > lastCycleEventCount) {
        let cycleEvent = null;

        const SLOW_MARGIN = Number(settings.slowCycleMarginPercent ?? 5); // 5% default

        if (
            actualCycleTime > 0 &&
            actualCycleTime > theoreticalCycleTime * (1 + SLOW_MARGIN / 100) &&
            actualCycleTime < microThresholdSec
        ) {
            const deltaPercent = ((actualCycleTime - theoreticalCycleTime) / theoreticalCycleTime) * 100;

            cycleEvent = {
                anomaly_type: "slow-cycle",
                severity: "warning",
                requires_ack: false,
                title: "Slow Cycle Detected",
                description: `Cycle took ${actualCycleTime.toFixed(1)}s (+${deltaPercent.toFixed(0)}% vs ${theoreticalCycleTime.toFixed(1)}s target)`,
                data: {
                    actual_cycle_time: actualCycleTime,
                    theoretical_cycle_time: theoreticalCycleTime,
                    delta_percent: Math.round(deltaPercent),
                    micro_threshold_multiplier: microMultiplier,
                    macro_threshold_multiplier: macroMultiplier
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: currentCycleCount,
                tsMs: now
            };

            //node.warn(`[SLOW-CYCLE] ${actualCycleTime.toFixed(1)}s (expected ${theoreticalCycleTime}s)`);

        } else if (actualCycleTime >= microThresholdSec && actualCycleTime < macroThresholdSec) {
            cycleEvent = {
                anomaly_type: "microstop",
                severity: "warning",
                requires_ack: false,
                title: "Microstop Detected",
                description: `Cycle gap ${actualCycleTime.toFixed(1)}s (threshold: ${microThresholdSec.toFixed(1)}s)`,
                data: {
                    stoppage_duration_seconds: Math.round(actualCycleTime),
                    theoretical_cycle_time: theoreticalCycleTime,
                    micro_threshold_multiplier: microMultiplier,
                    macro_threshold_multiplier: macroMultiplier
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: currentCycleCount,
                tsMs: now,
                status: "resolved"  // Changed to resolved since cycle completed
            };

            //node.warn(`[MICROSTOP] ${actualCycleTime.toFixed(1)}s gap detected`);

        } /*else if (actualCycleTime >= macroThresholdSec) {
            cycleEvent = {
                anomaly_type: "macrostop",
                severity: "critical",
                requires_ack: true,
                title: "Macrostop Detected",
                description: `Cycle gap ${actualCycleTime.toFixed(1)}s (threshold: ${macroThresholdSec.toFixed(1)}s)`,
                data: {
                    stoppage_duration_seconds: Math.round(actualCycleTime),
                    theoretical_cycle_time: theoreticalCycleTime,
                    micro_threshold_multiplier: microMultiplier,
                    macro_threshold_multiplier: macroMultiplier
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: currentCycleCount,
                tsMs: now,
                status: "resolved"  // Changed to resolved since cycle completed
            };

            node.warn(`[MACROSTOP] ${actualCycleTime.toFixed(1)}s gap detected`);
        }*/

        // FIXED: Always push cycle events (removed duplicate suppression)
        if (cycleEvent) {
            detectedAnomalies.push(cycleEvent);
            //node.warn(`[CYCLE EVENT] Added ${cycleEvent.anomaly_type} to detectedAnomalies`);
        }

        anomalyState.lastCycleEventCount = currentCycleCount;
        anomalyState.lastSlowCycleCount = currentCycleCount;
    }

    // No new cycle yet: start or escalate stoppage
    if (!hasNewCycle && lastCycleTime > 0) {
        // Start stoppage once when we cross micro threshold
        if (!anomalyState.activeStoppageEvent && timeSinceLastCycleSec >= microThresholdSec) {
            const isMacro = timeSinceLastCycleSec >= macroThresholdSec;
            const anomalyType = isMacro ? "macrostop" : "microstop";
            const severity = isMacro ? "critical" : "warning";

            const stoppageEvent = {
                alert_id: `${anomalyType}:${activeOrder.id}:${lastCycleTime}`,
                anomaly_type: anomalyType,
                severity,
                requires_ack: true,
                title: isMacro ? "Macrostop In Progress" : "Microstop In Progress",
                description: `No cycles for ${timeSinceLastCycleSec.toFixed(0)}s (expected cycle every ${theoreticalCycleTime}s)`,
                data: {
                    stoppage_duration_seconds: Math.round(timeSinceLastCycleSec),
                    theoretical_cycle_time: theoreticalCycleTime,
                    last_cycle_timestamp: lastCycleTime,
                    micro_threshold_multiplier: microMultiplier,
                    macro_threshold_multiplier: macroMultiplier
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: "active"
            };

            detectedAnomalies.push(stoppageEvent);
            anomalyState.activeStoppageEvent = stoppageEvent;
            anomalyState.lastStoppageUpdateMs = now;
            //node.warn(`[STOPPAGE START] ${anomalyType} started at ${timeSinceLastCycleSec.toFixed(0)}s`);
        }

        // Escalate micro -> macro once
        if (
            anomalyState.activeStoppageEvent &&
            anomalyState.activeStoppageEvent.anomaly_type === "microstop" &&
            timeSinceLastCycleSec >= macroThresholdSec
        ) {
            detectedAnomalies.push({
                ...anomalyState.activeStoppageEvent,
                status: "resolved",
                resolved_at: now,
                auto_resolved: true,
                requires_ack: false,
                data: {
                    ...anomalyState.activeStoppageEvent.data,
                    stoppage_duration_seconds: Math.round(timeSinceLastCycleSec)
                },
                tsMs: now
            });

            const macroEvent = {
                alert_id: `macrostop:${activeOrder.id}:${lastCycleTime}`,
                anomaly_type: "macrostop",
                severity: "critical",
                requires_ack: true,
                title: "Macrostop In Progress",
                description: `No cycles for ${timeSinceLastCycleSec.toFixed(0)}s (expected cycle every ${theoreticalCycleTime}s)`,
                data: {
                    stoppage_duration_seconds: Math.round(timeSinceLastCycleSec),
                    theoretical_cycle_time: theoreticalCycleTime,
                    last_cycle_timestamp: lastCycleTime,
                    micro_threshold_multiplier: microMultiplier,
                    macro_threshold_multiplier: macroMultiplier
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: "active"
            };

            detectedAnomalies.push(macroEvent);
            anomalyState.activeStoppageEvent = macroEvent;
            anomalyState.lastStoppageUpdateMs = now;
            //node.warn(`[ESCALATION] Microstop -> Macrostop at ${timeSinceLastCycleSec.toFixed(0)}s`);
        }

        // NEW: Send periodic updates for active macrostops
        if (
            anomalyState.activeStoppageEvent &&
            anomalyState.activeStoppageEvent.anomaly_type === "macrostop"
        ) {
            const timeSinceLastUpdate = now - (anomalyState.lastStoppageUpdateMs || 0);

            if (timeSinceLastUpdate >= updateIntervalMs) {
                const prev = anomalyState.activeStoppageEvent;

                // 1) AUTO-ACK the previous active macrostop alert
                const autoAck = {
                    ...prev,
                    status: "resolved",
                    resolved_at: now,
                    auto_resolved: true,
                    requires_ack: false,
                    title: "Macrostop Updated",
                    description: "Auto-acknowledged due to periodic refresh",
                    tsMs: now,
                    is_auto_ack: true
                };

                // 2) Send a NEW active macrostop alert with updated duration + NEW alert_id
                const refreshed = {
                    ...prev,
                    alert_id: `macrostop:${activeOrder.id}:${now}`, // new instance id so UI treats it as new
                    status: "active",
                    requires_ack: true,
                    title: "Macrostop Ongoing",
                    description: `Machine still stopped for ${timeSinceLastCycleSec.toFixed(0)}s (expected cycle every ${theoreticalCycleTime}s)`,
                    data: {
                        ...prev.data,
                        stoppage_duration_seconds: Math.round(timeSinceLastCycleSec)
                    },
                    kpi_snapshot: {
                        oee: kpis.oee || 0,
                        availability: kpis.availability || 0,
                        performance: kpis.performance || 0,
                        quality: kpis.quality || 0
                    },
                    tsMs: now,
                    is_update: true
                };

                detectedAnomalies.push(autoAck, refreshed);

                // IMPORTANT: set the active event to the refreshed one
                anomalyState.activeStoppageEvent = refreshed;
                anomalyState.lastStoppageUpdateMs = now;

                //node.warn(`[MACROSTOP REFRESH] Auto-acked previous, new duration: ${timeSinceLastCycleSec.toFixed(0)}s`);
            }
        }
    }
}



// ============================================================
// TIER 2: OEE DROP DETECTION
// Trigger: OEE falls below threshold
// ============================================================
const currentOEE = Number(kpis.oee) || 0;

if (currentOEE > 0) {
    const lowThreshold = OEE_THRESHOLD;       // e.g. 90
    const recoveryThreshold = OEE_THRESHOLD + 2; // some hysteresis

    if (currentOEE < lowThreshold) {
        // Count consecutive low points
        anomalyState.oeeLowStreak = (anomalyState.oeeLowStreak || 0) + 1;

        const REQUIRED_STREAK = 3; // only alert after 3 bad readings

        // Only fire when we ENTER the bad zone
        if (!anomalyState.activeOeeDrop &&
            anomalyState.oeeLowStreak >= REQUIRED_STREAK) {

            let severity = 'warning';
            if (currentOEE < 75) severity = 'critical';

            detectedAnomalies.push({
                anomaly_type: 'oee-drop',
                severity,
                title: 'OEE Below Threshold',
                description: `OEE at ${currentOEE.toFixed(1)}% (threshold: ${OEE_THRESHOLD}%)`,
                data: {
                    current_oee: currentOEE,
                    threshold: OEE_THRESHOLD,
                    delta: OEE_THRESHOLD - currentOEE
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: 'active'
            });

            anomalyState.activeOeeDrop = true;
            //node.warn(`[ANOMALY] OEE drop started at ${currentOEE.toFixed(1)}%`);
        }

    } else if (currentOEE >= recoveryThreshold) {
        // We are OUT of the bad zone
        anomalyState.oeeLowStreak = 0;

        if (anomalyState.activeOeeDrop) {
            detectedAnomalies.push({
                anomaly_type: 'oee-drop',
                severity: 'info',
                title: 'OEE Recovered',
                description: `OEE recovered to ${currentOEE.toFixed(1)}% (threshold: ${OEE_THRESHOLD}%)`,
                data: {
                    current_oee: currentOEE,
                    threshold: OEE_THRESHOLD
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: 'resolved'
            });

            anomalyState.activeOeeDrop = false;
            //node.warn(`[ANOMALY] OEE recovered to ${currentOEE.toFixed(1)}%`);
        }
    }
}

// Update OEE history for trend analysis
anomalyState.oeeHistory.push({ tsMs: now, value: currentOEE });
if (anomalyState.oeeHistory.length > HISTORY_WINDOW) {
    anomalyState.oeeHistory.shift();  // Keep only recent history
}

// ============================================================
// TIER 2: QUALITY SPIKE DETECTION
// Trigger: Sudden increase in scrap/defect rate
// ============================================================
const totalParts = (cycle.goodParts || 0) + (cycle.scrapParts || 0);
const currentScrapRate =
    totalParts > 0 ? ((cycle.scrapParts || 0) / totalParts) * 100 : 0;

// Keep history for trend
anomalyState.qualityHistory.push({ tsMs: now, value: currentScrapRate });
if (anomalyState.qualityHistory.length > HISTORY_WINDOW) {
    anomalyState.qualityHistory.shift();
}

// Only evaluate when we have enough data and enough volume in this cycle
const MIN_SAMPLES = 5;
const MIN_PARTS_THIS_CYCLE = 10;

if (
    anomalyState.qualityHistory.length >= MIN_SAMPLES &&
    totalParts >= MIN_PARTS_THIS_CYCLE
) {
    const recentHistory = anomalyState.qualityHistory.slice(0, -1); // exclude current
    const avgScrapRate =
        recentHistory.reduce((sum, p) => sum + p.value, 0) /
        recentHistory.length;

    const scrapRateIncrease = currentScrapRate - avgScrapRate;

    const SPIKE_DELTA = QUALITY_SPIKE_THRESHOLD || 5; // your existing config
    const MIN_SCRAP_RATE = 5; // ignore small scrap percentages
    const RECOVERY_MARGIN = 2; // how far back towards avg to consider "recovered"

    // ----- When scrap is HIGH / SPIKE ZONE -----
    if (
        currentScrapRate > MIN_SCRAP_RATE &&
        scrapRateIncrease > SPIKE_DELTA
    ) {
        // count how many consecutive "bad" cycles
        anomalyState.qualityHighStreak =
            (anomalyState.qualityHighStreak || 0) + 1;

        const REQUIRED_STREAK = 2; // require 2 consecutive bad cycles

        // fire ONLY when we ENTER the spike (not every cycle)
        if (
            !anomalyState.activeQualitySpike &&
            anomalyState.qualityHighStreak >= REQUIRED_STREAK
        ) {
            let severity = "warning";
            if (scrapRateIncrease > 10 || currentScrapRate > 15) {
                severity = "critical";
            }

            detectedAnomalies.push({
                anomaly_type: "quality-spike",
                severity,
                title: "Quality Issue Detected",
                description: `Scrap rate at ${currentScrapRate.toFixed(
                    1
                )}% (avg: ${avgScrapRate.toFixed(
                    1
                )}%, +${scrapRateIncrease.toFixed(1)}%)`,
                data: {
                    current_scrap_rate: currentScrapRate,
                    average_scrap_rate: avgScrapRate,
                    increase: scrapRateIncrease,
                    scrap_parts: cycle.scrapParts || 0,
                    total_parts: totalParts
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: "active"
            });

            anomalyState.activeQualitySpike = true;
            /*node.warn(
                `[ANOMALY] Quality spike started: scrap ${currentScrapRate.toFixed(
                    1
                )}% (avg ${avgScrapRate.toFixed(1)}%)`
            );*/
        }
    } else {
        // ----- When scrap is NORMAL / RECOVERY -----
        anomalyState.qualityHighStreak = 0;

        // if we had an active spike, send a single "resolved" event
        if (
            anomalyState.activeQualitySpike &&
            currentScrapRate <= avgScrapRate + RECOVERY_MARGIN
        ) {
            detectedAnomalies.push({
                anomaly_type: "quality-spike",
                severity: "info",
                title: "Quality Issue Resolved",
                description: `Scrap rate back to ${currentScrapRate.toFixed(
                    1
                )}% (avg: ${avgScrapRate.toFixed(1)}%)`,
                data: {
                    current_scrap_rate: currentScrapRate,
                    average_scrap_rate: avgScrapRate
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: "resolved"
            });

            anomalyState.activeQualitySpike = false;
            /*node.warn(
                `[ANOMALY] Quality spike resolved: scrap ${currentScrapRate.toFixed(
                    1
                )}%`
            );*/
        }
    }
}

// ============================================================
// TIER 2: PERFORMANCE DEGRADATION
// Trigger: Consistent underperformance over time
// ============================================================
const currentPerformance = Number(kpis.performance) || 0;
anomalyState.performanceHistory.push({ tsMs: now, value: currentPerformance });
if (anomalyState.performanceHistory.length > HISTORY_WINDOW) {
    anomalyState.performanceHistory.shift();
}

// Check for sustained poor performance (at least 10 data points)
if (anomalyState.performanceHistory.length >= 10) {
    const recent10 = anomalyState.performanceHistory.slice(-10);
    const avgPerformance = recent10.reduce((sum, point) => sum + point.value, 0) / recent10.length;

    const PERF_LOW_THRESHOLD = PERFORMANCE_THRESHOLD;      // 85%
    const PERF_RECOVERY_THRESHOLD = PERFORMANCE_THRESHOLD + 3;  // 88% to recover

    // Check if we're in degraded state
    if (avgPerformance > 0 && avgPerformance < PERF_LOW_THRESHOLD) {
        // Count consecutive low readings
        anomalyState.performanceLowStreak = (anomalyState.performanceLowStreak || 0) + 1;

        const REQUIRED_STREAK = 3;  // Need 3 consecutive low readings

        // Only fire ONCE when entering degraded state
        if (!anomalyState.activePerformanceDegradation &&
            anomalyState.performanceLowStreak >= REQUIRED_STREAK) {

            let severity = 'warning';
            if (avgPerformance < 75) {
                severity = 'critical';
            }

            detectedAnomalies.push({
                anomaly_type: 'performance-degradation',
                severity: severity,
                title: `Performance Degradation`,
                description: `Performance at ${avgPerformance.toFixed(1)}% (sustained over last 10 cycles)`,
                data: {
                    average_performance: avgPerformance,
                    current_performance: currentPerformance,
                    threshold: PERF_LOW_THRESHOLD,
                    sample_size: 10
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: 'active'
            });

            // Mark as active so we don't spam
            anomalyState.activePerformanceDegradation = true;
            //node.warn(`[ANOMALY] Performance degradation STARTED: ${avgPerformance.toFixed(1)}%`);
        }

    } else if (avgPerformance >= PERF_RECOVERY_THRESHOLD) {
        // Performance recovered
        anomalyState.performanceLowStreak = 0;

        // Only send recovery message if we were previously in degraded state
        if (anomalyState.activePerformanceDegradation) {
            detectedAnomalies.push({
                anomaly_type: 'performance-degradation',
                severity: 'info',
                title: 'Performance Recovered',
                description: `Performance recovered to ${avgPerformance.toFixed(1)}% (threshold: ${PERF_LOW_THRESHOLD}%)`,
                data: {
                    average_performance: avgPerformance,
                    current_performance: currentPerformance,
                    threshold: PERF_LOW_THRESHOLD
                },
                kpi_snapshot: {
                    oee: kpis.oee || 0,
                    availability: kpis.availability || 0,
                    performance: kpis.performance || 0,
                    quality: kpis.quality || 0
                },
                work_order_id: activeOrder.id,
                cycle_count: cycle.cycles || 0,
                tsMs: now,
                status: 'resolved'
            });

            anomalyState.activePerformanceDegradation = false;
            //node.warn(`[ANOMALY] Performance degradation RESOLVED: ${avgPerformance.toFixed(1)}%`);
        }
    }
}

// ============================================================
// TIER 3: PREDICTIVE ALERTS (Trend Analysis)
// Predict issues before they become critical
// ============================================================
if (anomalyState.oeeHistory.length >= 15) {
    // Simple linear trend analysis on OEE
    const recent15 = anomalyState.oeeHistory.slice(-15);
    const firstHalf = recent15.slice(0, 7);
    const secondHalf = recent15.slice(-7);

    const avgFirstHalf = firstHalf.reduce((sum, p) => sum + p.value, 0) / firstHalf.length;
    const avgSecondHalf = secondHalf.reduce((sum, p) => sum + p.value, 0) / secondHalf.length;

    const oeeTrend = avgSecondHalf - avgFirstHalf;

    // Predict if OEE is trending downward significantly
    if (oeeTrend < -5 && avgSecondHalf > OEE_THRESHOLD * 0.95 && avgSecondHalf < OEE_THRESHOLD * 1.05) {
        detectedAnomalies.push({
            anomaly_type: 'predictive-oee-decline',
            severity: 'info',
            title: `Declining OEE Trend Detected`,
            description: `OEE trending down ${Math.abs(oeeTrend).toFixed(1)}% over last 15 cycles. Current: ${avgSecondHalf.toFixed(1)}%`,
            data: {
                trend: oeeTrend,
                first_half_avg: avgFirstHalf,
                second_half_avg: avgSecondHalf,
                prediction: 'OEE may drop below threshold soon'
            },
            kpi_snapshot: {
                oee: kpis.oee || 0,
                availability: kpis.availability || 0,
                performance: kpis.performance || 0,
                quality: kpis.quality || 0
            },
            work_order_id: activeOrder.id,
            cycle_count: cycle.cycles || 0,
            tsMs: now
        });

        //node.warn(`[PREDICTIVE] OEE trending down: ${oeeTrend.toFixed(1)}%`);
    }
}

// Update last cycle time for next iteration
anomalyState.lastCycleTime = lastCycleTime;
global.set("anomalyState", anomalyState, "file");
//anomaly.state = anomalyState;
//global.set("anomaly", anomaly);


