            { label: 'Availability %', data: smoothAvail },
            { label: 'Performance %',  data: smoothPerf },
            { label: 'Quality %',      data: smoothQual }
        ]
    };

    //node.warn(`[GRAPH DATA] Formatted ${labels.length} KPI history points`);

