  } else if (v && typeof v.toISOString === "function") {
    // Some date-like objects
    awo.lastUpdateIso = v.toISOString();
  } else if (v && typeof v.format === "function") {
    // Moment-like
    awo.lastUpdateIso = v.format();
  } else {
    // Last resort: try to stringify, otherwise null it out
    awo.lastUpdateIso = v ? String(v) : null;
  }
  node.warn(`[lastUpdateIso] typeof=${typeof v} value=${v}`);
  node.warn(`[lastUpdateIso] JSON=${JSON.stringify(v)}`);
}

return msg;

var ssids = msg.payload.split('\n').filter(s => !!s)

ssids = [...new Set(ssids)];

msg.options = ssids
msg.payload = null

return msg;

function grab(re){
  const m = msg.payload.match(re);
  return m ? m[1] : null;
}

const ip = grab(/inet ([0-9\.]+)/);
const mask = grab(/netmask ([0-9\.]+)/);
const broadcast = grab(/broadcast ([0-9\.]+)/);

node.send({topic:"ip", payload: ip});
node.send({topic:"mask", payload: mask});
node.send({topic:"broadcast", payload: broadcast});

return null;

msg.topic = "wifi:scan:result";
msg.payload = msg.options || [];
delete msg.options;
return msg;

const ok = (msg.payload || "").trim() === "OK";
msg.topic = "wifi:apply:result";
msg.payload = {
  ok,
  message: ok ? "WiFi updated. Reconnecting…" : "Error updating WiFi. Check password/SSID."
};
return msg;

msg.topic = "wifi:status:result";
msg.payload = {
  ssid: msg.payload.ssid || null,
  ip: msg.payload.ip || null,
  mask: msg.payload.mask || null,
  broadcast: msg.payload.broadcast || null
};
return msg;
